custom_css:
/* 《老派约会之必要》@夜行性鲨鱼
禁商用禁二传禁二改（也给我吃一口的话可以二改₍ᐢ.ˬ.ᐢ₎
带符号🤍的地方是自定义文字区域
右上角深灰色小框是消息编辑功能，浅灰色小框按理来说也能用……暂时懒得改了！ */

/* 1. 全局背景与滚动条 */
body{background-color:#EFEFEF!important;background-image:linear-gradient(45deg,#E5E5E5 25%,transparent 25%,transparent 75%,#E5E5E5 75%,#E5E5E5),linear-gradient(45deg,#E5E5E5 25%,transparent 25%,transparent 75%,#E5E5E5 75%,#E5E5E5)!important;background-size:40px 40px!important;background-position:0 0,20px 20px!important;}
::-webkit-scrollbar{display:none;}

/* 2. 顶栏极窄精简 */
#top-bar{height:34px!important;min-height:34px!important;background-color:#fff!important;box-shadow:none!important;border-bottom:1px solid #E0E0E0!important;display:flex!important;align-items:center!important;justify-content:center!important;padding:0!important;overflow:hidden!important;}
.drawer-toggle{height:34px!important;width:40px!important;line-height:34px!important;display:flex!important;align-items:center!important;justify-content:center!important;margin:0!important;padding:0!important;}
.drawer-icon{font-size:16px!important;color:#A0A0A0!important;transition:color 0.2s ease!important;}
.drawer-icon:hover{color:#333!important;}
.top-bar-border{display:none!important;}

/* 3. 聊天流总体布局 */
#chat{padding-top:15px!important;padding-bottom:80px!important;gap:40px!important;background:transparent!important;display:flex;flex-direction:column;}

/* 4. 窗口主体 (已增加 [mesid] 限定防污染) */
#chat .mes[mesid]{position:relative!important;background:#fff!important;width:90%!important;max-width:850px!important;margin:0 auto!important;padding:0!important;border:1px solid #D0D0D0!important;border-radius:0!important;box-shadow:4px 4px 15px rgba(0,0,0,0.05)!important;display:flex!important;flex-direction:column!important;}
/* 🤍顶部窗口栏 */
#chat .mes[mesid]::before{content:"# 李维菁";display:block;width:100%;height:40px;line-height:40px;background:#fff;color:#999;font-size:14px;padding-left:20px;border-bottom:1px solid #E0E0E0;box-sizing:border-box;flex-shrink:0;background-image:linear-gradient(#ccc,#ccc),linear-gradient(#666,#666);background-size:14px 14px,14px 14px;background-position:calc(100% - 40px) 13px,calc(100% - 15px) 13px;background-repeat:no-repeat;}
/* 🤍底部签名 */
#chat .mes[mesid]::after{content:"ㅎㅇ...🤍";position:absolute!important;bottom:15px!important;right:30px!important;font-size:16px;color:#A0A0A0;font-weight:700;letter-spacing:2px;pointer-events:none;}
#chat .mes[mesid] .mes_block{display:flex!important;flex-direction:column!important;width:100%!important;padding:0!important;margin:0!important;box-sizing:border-box!important;border:none!important;background:transparent!important;flex-grow:1;}

/* 5. 头像与元数据(拍立得加高版) */
#chat .mes[mesid] .mesAvatarWrapper{position:absolute!important;top:0!important;left:0!important;width:100%!important;height:100%!important;margin:0!important;padding:0!important;border:none!important;background:transparent!important;pointer-events:none!important;}
#chat .mes[mesid] .avatar{position:absolute!important;top:70px!important;left:30px!important;width:160px!important;height:280px!important;border-radius:0!important;border:1px solid #DDD!important;padding:6px!important;background:#fff!important;box-shadow:2px 2px 8px rgba(0,0,0,0.05)!important;box-sizing:border-box!important;pointer-events:auto!important;}
#chat .mes[mesid] .avatar img{width:100%!important;height:100%!important;border-radius:0!important;object-fit:cover!important;}
#chat .mes[mesid] .avatar::before, #chat .mes[mesid] .avatar::after{display:none!important;}
/* 计时器楼层等 */
#chat .mes[mesid] .mesIDDisplay, #chat .mes[mesid] .mes_timer, #chat .mes[mesid] .tokenCounterDisplay{position:absolute!important;bottom:45px!important;font-size:12px!important;color:#A0A0A0!important;background:transparent!important;border:none!important;box-shadow:none!important;margin:0!important;line-height:1.2!important;pointer-events:auto!important;}
#chat .mes[mesid] .tokenCounterDisplay{right:30px!important;}
#chat .mes[mesid] .mes_timer{right:100px!important;}
#chat .mes[mesid] .mesIDDisplay{right:180px!important;}

/* 🤍6. 名字与七行诗排版 */
#chat .mes[mesid] .ch_name{display:flex!important;flex-direction:row!important;justify-content:space-between!important;align-items:flex-start!important;margin-left:220px!important;margin-right:30px!important;padding-top:30px!important;min-height:320px!important;background:transparent!important;border:none!important;}
#chat .mes[mesid] .ch_name>.flex-container.flex1{display:flex!important;flex-direction:column!important;align-items:flex-start!important;width:100%;padding-bottom:25px!important;}
#chat .mes[mesid] .ch_name .alignItemsBaseline{display:flex!important;flex-direction:row!important;flex-wrap:wrap!important;align-items:baseline!important;width:100%;}
#chat .mes[mesid] .ch_name .name_text{font-size:26px!important;font-weight:700!important;color:#333!important;letter-spacing:1px!important;margin-right:15px;}
#chat .mes[mesid] .timestamp{position:static!important;font-size:14px!important;color:#A0A0A0!important;margin:0!important;}
#chat .mes[mesid] .ch_name .alignItemsBaseline::after{content:"《老派约会之必要》";display:block;width:100%;font-size:18px;color:#BBB;margin-top:8px;margin-bottom:12px;}
#chat .mes[mesid] .ch_name>.flex-container.flex1::after{content:"我依赖的人，砍掉他的手。\A我渴望的人，划花他的脸。\A我崇拜的人，戳穿他的心。\A我好奇的人，阉割他的脑。\A我爱的人，杀死他，全部。\A没有人可以让我牵挂，\A一个也不能留，我天下无敌";white-space:pre-wrap;display:block;font-size:15px;color:#777;line-height:1.9;}

/* 7. 悬浮按钮(覆盖到顶栏右侧方块) */
#chat .mes[mesid] .mes_buttons{position:absolute!important;top:0!important;right:0!important;width:100px;height:40px!important;z-index:10;pointer-events:none;}
#chat .mes[mesid] .mes_buttons .mes_button{display:none!important;}
#chat .mes[mesid] .mes_buttons .extraMesButtonsHint, #chat .mes[mesid] .mes_buttons .mes_edit{display:block!important;position:absolute!important;top:10px!important;width:20px!important;height:20px!important;font-size:0!important;background:transparent!important;border:none!important;box-shadow:none!important;opacity:1!important;cursor:pointer;pointer-events:auto!important;}
#chat .mes[mesid] .mes_buttons .extraMesButtonsHint{right:32px!important;}
#chat .mes[mesid] .mes_buttons .mes_edit{right:7px!important;}

/* 8. 正文气泡区域 */
#chat .mes[mesid] .mes_text{background-color:#F8F8F8!important;width:96%!important;margin:10px auto 80px auto!important;padding:20px!important;color:#444!important;line-height:2.0!important;border:1px solid #EEE!important;border-radius:0!important;position:relative;box-sizing:border-box!important;}
#chat .mes[mesid] .mes_text::before, #chat .mes[mesid] .mes_text::after{display:none!important;}

/* 9. UI与面板修复(含预设白字BUG修复) */
.standoutHeader,.title_restorable,.inline-drawer-header,#user-settings-block h4,h4[data-i18n],.persona_management_global_settings h4{background-color:#F9F9F9!important;background-image:none!important;border:1px solid #E0E0E0!important;color:#555!important;border-radius:0!important;text-shadow:none!important;}
.text_pole,textarea,select,.drawer-content,.menu_button{background-color:#fff!important;border:1px solid #CCC!important;color:#444!important;border-radius:0!important;}
.range-block-counter input,.neo-range-input{background-color:#fff!important;border:1px solid #CCC!important;color:#333!important;border-radius:0!important;}
/* 核心修复:防止被禁用输入框内文字变白消失 */
input:disabled,textarea:disabled,.text_pole:disabled,#completion_prompt_manager_list input,.completion_prompt_manager_prompt_name{color:#333!important;-webkit-text-fill-color:#333!important;opacity:1!important;}
/* 预设列表优化白底纸质风格 */
.completion_prompt_manager_list_item,#completion_prompt_manager_list{background-color:#FAFAFA!important;border:1px solid #E0E0E0!important;}
.text_pole:focus,textarea:focus,select:focus{border-color:#888!important;box-shadow:0 0 5px rgba(0,0,0,0.1)!important;outline:none!important;}
.menu_button:hover{background-color:#EEE!important;color:#111!important;}
#send_form{background:#fff!important;border:1px solid #DDD!important;border-radius:0!important;box-shadow:4px 4px 0 rgba(0,0,0,0.05)!important;}
#send_textarea{color:#333!important;}

/* 10. 移动端排版保护 */
@media screen and (max-width:800px){
    #top-bar{height:32px!important;}
    .drawer-toggle{width:34px!important;}
    .drawer-icon{font-size:15px!important;}
    #chat .mes[mesid]{width:90%!important;}
    #chat .mes[mesid] .avatar{width:100px!important;height:260px!important;left:15px!important;}
    #chat .mes[mesid] .ch_name{margin-left:130px!important;margin-right:15px!important;min-height:290px!important;}
    #chat .mes[mesid] .ch_name .name_text{font-size:20px!important;}
    #chat .mes[mesid] .timestamp{font-size:12px!important;}
    #chat .mes[mesid] .ch_name .alignItemsBaseline::after{font-size:16px;margin-top:5px;}
    #chat .mes[mesid] .ch_name>.flex-container.flex1::after{font-size:13px;}
    #chat .mes[mesid] .mes_text{width:94%!important;padding:15px!important;margin-bottom:80px!important;}
}
